import { useState } from "react";
import { SectionPage, Specimen } from "../kit.js";
import { IconOrganisation } from "../../icons/generated/icons.js";
import {
  Window,
  WindowManagerProvider,
  WindowSwitcher,
  createWindowManager,
  registerWindowKind,
} from "../../windows/index.js";
import { Button } from "../../ui/button/index.js";

function SampleWindowBody() {
  return (
    <Window.Body>
      <p>Fictional exhibition notes.</p>
    </Window.Body>
  );
}

// Kinds register once at module scope, never during render: registering notifies every
// mounted WindowContentHost.
registerWindowKind({
  kind: "docs.notes",
  icon: IconOrganisation,
  title: () => "Exhibition notes",
  load: async () => ({ default: SampleWindowBody }),
});

function makeWindowDemo() {
  const manager = createWindowManager({ storageKey: null, channelName: null });
  const id = manager.open({ kind: "docs.notes", params: {} });
  return { manager, id };
}

export default function WindowSwitcherExample() {
  const [{ manager }] = useState(makeWindowDemo);
  const [open, setOpen] = useState(false);
  return (
    <SectionPage>
      <Specimen
        title="Choose an open window"
        layout="stack"
        specimenKey="component-examples:WindowSwitcherExample:0"
      >
        <WindowManagerProvider manager={manager}>
          <Button onClick={() => setOpen(true)}>Switch window</Button>
          <WindowSwitcher open={open} onOpenChange={setOpen} />
        </WindowManagerProvider>
      </Specimen>
    </SectionPage>
  );
}
